//! The post-import DBID calibration acceptance cases (BW-09-07-06):
//! after explicit ids were written by an import, newly created entities
//! do not collide with them.
//!
//! The collision is real before calibration: `GENERATED BY DEFAULT AS
//! IDENTITY` does not advance the sequence for an explicit value, so a
//! create hands out an id the imported rows may already hold — the
//! duplicate-primary-key outcome of the reference's `insertExplicit`
//! (`put_entity_task.cpp:93-97`). The reference never recalibrates: its
//! `AUTO_INCREMENT` state travels inside the copied datadir, and its
//! only row-merge path replays rows into a live primary
//! (`consolidate_entity_task.cpp:27-34`), so the calibration step is the
//! port's own. The same server gate as `dbid.rs`: `BOUNDLESS_PG_URL`,
//! the CI storage service's `CI_STORE_PG_*`, or a local unix socket; a
//! private database per case, dropped when it finishes.

use std::sync::atomic::{AtomicU32, Ordering};

use db::DbError;
use db_postgres::{EntitySchema, PostgresStorage};
use entitydef::value::PropertyValue;

static TEST_DB_COUNTER: AtomicU32 = AtomicU32::new(0);

/// The libpq connection string for the admin connection, without a
/// database: `BOUNDLESS_PG_URL`, the CI storage service, or the local
/// server's unix socket.
fn admin_conninfo() -> Option<String> {
    if let Ok(url) = std::env::var("BOUNDLESS_PG_URL") {
        return Some(url);
    }
    if let (Ok(host), Ok(port)) = (
        std::env::var("CI_STORE_PG_HOST"),
        std::env::var("CI_STORE_PG_PORT"),
    ) {
        let password = std::env::var("CI_STORE_PG_PASSWORD").unwrap_or_default();
        return Some(format!(
            "host={host} port={port} dbname=postgres user=boundless password={password}"
        ));
    }
    // A local server's unix socket: peer authentication, the OS account's
    // own role.
    let user = whoami();
    Some(format!(
        "host=/var/run/postgresql dbname=postgres user={user}"
    ))
}

fn whoami() -> String {
    std::env::var("USER")
        .or_else(|_| std::env::var("LOGNAME"))
        .unwrap_or_else(|_| "postgres".to_string())
}

/// Runs `body` against a fresh private database on its own storage. The
/// database is dropped when the body returns.
fn with_fresh_db(body: impl FnOnce(&mut PostgresStorage)) {
    let Some(admin_conninfo) = admin_conninfo() else {
        eprintln!("skipping: set BOUNDLESS_PG_URL to run the postgres cases");
        return;
    };
    let mut admin = match PostgresStorage::connect(&admin_conninfo) {
        Ok(admin) => admin,
        Err(err) => {
            eprintln!("skipping: no reachable postgres server ({err})");
            return;
        }
    };
    let database = format!(
        "boundless_pg_calib_{}_{}",
        std::process::id(),
        TEST_DB_COUNTER.fetch_add(1, Ordering::SeqCst)
    );
    let quoted = database.replace('"', "\"\"");
    if let Err(err) = admin
        .client_mut()
        .execute(format!("CREATE DATABASE \"{quoted}\"").as_str(), &[])
    {
        eprintln!("skipping: cannot create the test database ({err})");
        return;
    }
    let conninfo = format!("{admin_conninfo} dbname={database}");
    let result = PostgresStorage::connect(&conninfo).map(|mut storage| body(&mut storage));
    let _ = admin.client_mut().execute(
        format!("DROP DATABASE \"{quoted}\" WITH (FORCE)").as_str(),
        &[],
    );
    if let Err(err) = result {
        panic!("the fresh database would not open: {err}");
    }
}

fn account_schema() -> EntitySchema {
    EntitySchema::for_record(
        "Account",
        &["name", "level"],
        &[PropertyValue::String("cui".into()), PropertyValue::Int(1)],
    )
    .unwrap()
}

fn values() -> Vec<PropertyValue> {
    vec![PropertyValue::String("cui".into()), PropertyValue::Int(1)]
}

/// One imported row: an explicit id written straight into the table.
fn imported_row(db_id: i64) -> db::EntityRecord {
    let mut record = db::EntityRecord::new(0);
    record.db_id = db_id;
    record.values = values();
    record
}

/// The acceptance: an import writes explicit ids, calibration moves the
/// sequence past them, and every create afterwards is safe — it takes
/// the id calibration returned and collides with nothing.
#[test]
fn creates_after_an_import_do_not_collide() {
    with_fresh_db(|storage| {
        let schema = account_schema();
        storage.create_entity_table(&schema).unwrap();

        // The import: explicit ids in no particular order, written the
        // way the import and restore paths write them. `1` is among them
        // because an imported MySQL table numbers its rows from 1.
        for db_id in [77, 1, 300] {
            storage.put_entity(&schema, &imported_row(db_id)).unwrap();
        }

        // Without calibration the sequence is still untouched, so the
        // first create asks for 1 and collides with the imported row —
        // the failure this item exists to remove.
        let err = storage.create_entity(&schema, &values()).unwrap_err();
        assert_eq!(err, DbError::AlreadyExists);

        let next = storage.calibrate_dbid_allocation(&schema).unwrap();
        assert_eq!(next, 301, "calibration must move past the max imported id");
        assert_eq!(storage.next_allocatable_id(&schema).unwrap(), next);

        // Every create is safe, and the imported rows are untouched.
        for expected in [301, 302, 303] {
            let id = storage.create_entity(&schema, &values()).unwrap();
            assert_eq!(id, expected);
            let back = storage
                .get_entity(
                    &schema,
                    &db::EntityKey {
                        type_id: 0,
                        db_id: id,
                    },
                )
                .unwrap()
                .unwrap();
            assert_eq!(back.values, values());
        }
        for db_id in [1, 77, 300] {
            let back = storage
                .get_entity(&schema, &db::EntityKey { type_id: 0, db_id })
                .unwrap()
                .unwrap();
            assert_eq!(back.values, values());
        }
    });
}

/// Calibration consumes no id itself and is repeatable: running it twice
/// leaves the same next allocatable DBID, so a retried migration does
/// not burn ids.
#[test]
fn calibration_consumes_nothing_and_is_repeatable() {
    with_fresh_db(|storage| {
        let schema = account_schema();
        storage.create_entity_table(&schema).unwrap();

        // A table the database itself allocated for, then an import.
        storage.create_entity(&schema, &values()).unwrap();
        storage.put_entity(&schema, &imported_row(50)).unwrap();

        let first = storage.calibrate_dbid_allocation(&schema).unwrap();
        assert_eq!(first, 51);
        let second = storage.calibrate_dbid_allocation(&schema).unwrap();
        assert_eq!(second, first, "the second calibration burned an id");
        assert_eq!(storage.next_allocatable_id(&schema).unwrap(), first);
        assert_eq!(storage.create_entity(&schema, &values()).unwrap(), first);
    });
}

/// An import that brought no rows calibrates to the start value: the
/// first create takes id 1, exactly what a fresh table would hand out.
#[test]
fn an_empty_imported_table_calibrates_to_its_start_value() {
    with_fresh_db(|storage| {
        let schema = account_schema();
        storage.create_entity_table(&schema).unwrap();

        let next = storage.calibrate_dbid_allocation(&schema).unwrap();
        assert_eq!(next, 1);
        assert_eq!(storage.create_entity(&schema, &values()).unwrap(), 1);
    });
}
